#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
vector<long long> factArr(200001);
vector<long long> invFactArr(200001);

long long powMod(long long base, long long exp, long long mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

void precomputeFactorials() {
    factArr[0] = 1;
    invFactArr[0] = 1;
    for (int i = 1; i <= 200000; i++) {
        factArr[i] = (factArr[i - 1] * i) % MOD;
        invFactArr[i] = powMod(factArr[i], MOD - 2, MOD);
    }
}

long long ncr(int n, int r) {
    return (((factArr[n] * invFactArr[r]) % MOD) * invFactArr[n - r]) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    precomputeFactorials();
    long long n, k;
    cin >> n >> k;
    if (k > n) {
        cout << 0 << "\n";
        return 0;
    }
    long long remaining = n - k;
    long long sum = 0;
    for (int i = 0; i <= remaining; i++) {
        long long val = (ncr(remaining, i) * powMod(remaining - i, n, MOD)) % MOD;
        if (i % 2 == 0) sum += val;
        else sum -= val;
        sum = (sum + MOD) % MOD;
    }
    long long answer = (sum * ncr(n, remaining)) % MOD;
    if (remaining == 0) {
        cout << answer << "\n";
    } else {
        cout << (2 * answer) % MOD << "\n";
    }
    return 0;
}
